import os

import pytest


@pytest.fixture
def graph():
    from routeplan.graph import load_graph
    return load_graph("tests/fixtures/city.json")


_SLOW_IN_CI = {"test_eta_for_long_route", "test_eta_matrix_full_city"}


def pytest_collection_modifyitems(config, items):
    if not os.environ.get("CI"):
        return
    kept = [item for item in items if item.name not in _SLOW_IN_CI]
    config.hook.pytest_deselected(items=[i for i in items if i not in kept])
    items[:] = kept
